SELECT p.mode_of_payment,p.payment_account,SUM(p.amount) AS amount FROM "tabPOS Invoice" h JOIN "tabPOS Payment" p ON p.parent=h.name AND p.parenttype='POS Invoice' WHERE h.docstatus=1 AND (%(company)s='' OR h.company=%(company)s) AND (%(from_date)s='' OR h.posting_date>=%(from_date)s) AND (%(to_date)s='' OR h.posting_date<=%(to_date)s) GROUP BY p.mode_of_payment,p.payment_account ORDER BY amount DESC
